# Origin decides policy. Edge enforces it.
# Immutable build artifact: never purge, just rename on deploy.
location ~* \.[a-f0-9]{8}\.(js|css|woff2|png)$ {
  add_header Cache-Control "public, max-age=31536000, immutable";
  add_header Surrogate-Key "static-$1";
}

# Public API: short edge TTL, background refresh hides origin slowness.
location /api/v1/feed {
  add_header Cache-Control "public, s-maxage=60, max-age=30, stale-while-revalidate=120, stale-if-error=600";
  add_header Vary "Accept-Encoding, Accept-Language";
  # Never cache authenticated variants at edge as public
  add_header Surrogate-Key "feed";
}

# Private: must never sit on shared edge.
location /api/v1/me {
  add_header Cache-Control "private, no-store";
}

# What to run at the edge (worker / edge function) before cache lookup.
# Goal: collapse marketing noise into one key, keep real variants separate.
ALLOWLIST = {"page", "lang", "v"}

def normalize_key(path: str, query: dict, headers: dict) -> str:
    # Trade-off: stripping params raises hit ratio but risks
    # collapsing truly different content. Allowlist, don't blocklist.
    clean = {k: v for k, v in query.items() if k in ALLOWLIST}
    lang = (headers.get("accept-language", "en") or "en").split(",")[0].lower()
    # Never include cookies/auth in public key; bypass instead.
    if headers.get("authorization") or headers.get("cookie"):
        return "BYPASS:authenticated"
    suffix = "&".join(f"{k}={clean[k]}" for k in sorted(clean))
    return f"{path.lower().rstrip('/')}|lang={lang}|q={suffix}"
